-- AI model library (#130): AI models (not real people) a seller picks for an on-model image (#121). The admin
-- manages the library and uploads every reference photo; nothing here is generated by the API.
--
-- 1. ai_models: one model with its audience, skin tone and style. A model is never deleted, only deactivated:
--    a deactivated model is not offered for new jobs, images approved earlier stay on their products.
--    At most one active default per audience.
-- 2. ai_model_images: reference photos in the public bucket (ai-models/<model>/<uuid>.<ext>), one pose each, so
--    results stay consistent (same face and proportions).
-- 3. ai_jobs.model_id: the model a VIRTUAL_TRY_ON job uses.

CREATE TABLE ai_models
(
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Invented working name, shown to sellers.
    name       TEXT        NOT NULL,
    audience   TEXT        NOT NULL,
    skin_tone  TEXT        NOT NULL,
    style      TEXT        NOT NULL,
    -- How the model was made (tool and date), copied to docs/credits.md.
    origin     TEXT        NOT NULL,
    active     BOOLEAN     NOT NULL DEFAULT TRUE,
    is_default BOOLEAN     NOT NULL DEFAULT FALSE,
    sort_order INT         NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ai_models_name CHECK (length(btrim(name)) BETWEEN 1 AND 60),
    CONSTRAINT ai_models_origin CHECK (length(btrim(origin)) BETWEEN 1 AND 300),
    CONSTRAINT ai_models_audience CHECK (audience IN ('WOMEN', 'MEN', 'KIDS')),
    CONSTRAINT ai_models_skin_tone CHECK (skin_tone IN ('LIGHT', 'MEDIUM_LIGHT', 'MEDIUM', 'MEDIUM_DARK', 'DARK')),
    CONSTRAINT ai_models_style CHECK (style IN ('CLASSIC', 'CASUAL', 'EVENING', 'MINIMAL')),
    CONSTRAINT ai_models_default_active CHECK (NOT is_default OR active)
);

CREATE UNIQUE INDEX ai_models_one_default_idx ON ai_models (audience) WHERE is_default;

CREATE TABLE ai_model_images
(
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    model_id     BIGINT      NOT NULL REFERENCES ai_models (id) ON DELETE CASCADE,
    storage_key  TEXT        NOT NULL UNIQUE,
    pose         TEXT        NOT NULL,
    content_type TEXT        NOT NULL,
    width        INT         NOT NULL,
    height       INT         NOT NULL,
    size_bytes   BIGINT      NOT NULL,
    sort_order   INT         NOT NULL DEFAULT 0,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ai_model_images_pose CHECK (pose IN ('HAND', 'EAR', 'NECK', 'WRIST', 'HALF_PORTRAIT')),
    CONSTRAINT ai_model_images_type CHECK (content_type IN ('image/jpeg', 'image/png', 'image/webp')),
    CONSTRAINT ai_model_images_size CHECK (width > 0 AND height > 0 AND size_bytes > 0)
);

CREATE INDEX ai_model_images_model_idx ON ai_model_images (model_id, sort_order);

ALTER TABLE ai_jobs
    ADD COLUMN model_id BIGINT REFERENCES ai_models (id) ON DELETE SET NULL;
